          <el-table :data="data.limit_monitor || []" size="small" border max-height="350"><el-table-column prop="dimension_type" label="维度" width="100"><template #default="{ row }">{{ dimensionLabel(row.dimension_type) }}</template></el-table-column><el-table-column prop="scope_name" label="范围" min-width="145" show-overflow-tooltip /><el-table-column prop="metric_code" label="指标" width="92"><template #default="{ row }">{{ metricLabel(row.metric_code) }}</template></el-table-column><el-table-column label="当前值" min-width="112" align="right"><template #default="{ row }">{{ amount(row.actual_amount) }}</template></el-table-column><el-table-column label="限额" min-width="112" align="right"><template #default="{ row }">{{ amount(row.limit_amount) }}</template></el-table-column><el-table-column label="使用率" width="92" align="right"><template #default="{ row }">{{ percent(row.utilization_ratio) }}</template></el-table-column><el-table-column label="状态" width="88"><template #default="{ row }"><el-tag size="small" :type="limitType(row.monitor_status)" effect="plain">{{ limitLabel(row.monitor_status) }}</el-tag></template></el-table-column><el-table-column label="操作" width="64" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="editLimit(row)">调整</el-button></template></el-table-column></el-table>
