          <el-table :data="data.group_risk || []" size="small" border max-height="500" @row-click="openGroup"><el-table-column prop="group_name" label="集团" min-width="160" fixed="left"><template #default="{ row }"><el-link type="primary" :underline="false">{{ row.group_name }}</el-link></template></el-table-column><el-table-column prop="member_count" label="成员" width="75" align="right" /><el-table-column prop="exposure_count" label="债项" width="75" align="right" /><el-table-column label="集团 EAD" min-width="115" align="right"><template #default="{ row }">{{ compactAmount(row.ead_amount) }}</template></el-table-column><el-table-column label="衰退 EL" min-width="105" align="right"><template #default="{ row }">{{ compactAmount(row.el_downturn_amount) }}</template></el-table-column><el-table-column label="偏好使用率" width="105" align="right"><template #default="{ row }">{{ percent(row.appetite_utilization) }}</template></el-table-column><el-table-column label="押品覆盖" width="95" align="right"><template #default="{ row }">{{ percent(row.collateral_coverage) }}</template></el-table-column><el-table-column prop="overdue_count" label="逾期" width="72" align="right" /><el-table-column prop="default_count" label="违约" width="72" align="right" /><el-table-column label="状态" width="88"><template #default="{ row }"><el-tag size="small" :type="Number(row.default_count) ? 'danger' : Number(row.appetite_utilization) >= .8 ? 'warning' : 'success'" effect="plain">{{ Number(row.default_count) ? '高风险' : Number(row.appetite_utilization) >= .8 ? '关注' : '正常' }}</el-tag></template></el-table-column></el-table>
