        <article class="panel lifecycle-panel"><div class="panel-title"><div><h3>模型版本生命周期</h3><span>版本创建、模拟、提交、审批、发布与运行监控全过程</span></div></div>
          <el-table :data="data.model_lifecycle || []" size="small" border max-height="440"><el-table-column prop="version_code" label="版本" min-width="145" fixed="left" /><el-table-column prop="version_name" label="名称" min-width="160" /><el-table-column prop="lifecycle_stage" label="阶段" width="100"><template #default="{ row }"><el-tag size="small" effect="plain">{{ row.lifecycle_stage }}</el-tag></template></el-table-column><el-table-column prop="rule_count" label="规则" width="70" align="right" /><el-table-column label="模拟时间" min-width="135"><template #default="{ row }">{{ formatDate(row.simulated_at) }}</template></el-table-column><el-table-column label="审批时间" min-width="135"><template #default="{ row }">{{ formatDate(row.approved_at) }}</template></el-table-column><el-table-column label="发布时间" min-width="135"><template #default="{ row }">{{ formatDate(row.published_at) }}</template></el-table-column><el-table-column prop="approval_action_count" label="审计动作" width="90" align="right" /></el-table>
