        <article class="panel"><div class="panel-title"><div><h3>模型回溯与校准</h3><span>比较预期 PD/LGD、预测违约 EAD 与实际违约表现</span></div><el-button type="primary" :icon="TrendCharts" :loading="backtesting" @click="runBacktest">执行回溯</el-button></div>
          <el-table :data="data.latest_backtest || []" size="small" border max-height="470"><el-table-column prop="segment_type" label="分段维度" width="100"><template #default="{ row }">{{ dimensionLabel(row.segment_type) }}</template></el-table-column><el-table-column prop="segment_name" label="分段" min-width="140" /><el-table-column label="预期 PD" width="92" align="right"><template #default="{ row }">{{ percent(row.expected_pd) }}</template></el-table-column><el-table-column label="实际违约率" width="102" align="right"><template #default="{ row }">{{ percent(row.observed_default_rate) }}</template></el-table-column><el-table-column label="预期 LGD" width="92" align="right"><template #default="{ row }">{{ percent(row.expected_lgd) }}</template></el-table-column><el-table-column label="实际 LGD" width="92" align="right"><template #default="{ row }">{{ percent(row.observed_lgd) }}</template></el-table-column><el-table-column label="EAD 偏差" width="92" align="right"><template #default="{ row }">{{ signedPercent(row.ead_bias) }}</template></el-table-column><el-table-column label="状态" width="96"><template #default="{ row }"><el-tag size="small" :type="calibrationType(row.calibration_status)" effect="plain">{{ calibrationLabel(row.calibration_status) }}</el-tag></template></el-table-column><el-table-column prop="recommendation" label="校准建议" min-width="220" show-overflow-tooltip /></el-table>
        </article>
      </el-tab-pane>

      <el-tab-pane label="预警处置效果" name="effectiveness">
        <section class="effect-metrics"><div><span>已评价</span><strong>{{ number(data.effectiveness_metrics?.evaluated_count) }}</strong></div><div><span>有效率</span><strong>{{ percent(data.effectiveness_metrics?.effective_rate) }}</strong></div><div><span>风险改善率</span><strong>{{ percent(data.effectiveness_metrics?.improvement_rate) }}</strong></div><div><span>无效率</span><strong class="danger">{{ percent(data.effectiveness_metrics?.ineffective_rate) }}</strong></div><div><span>平均评分改善</span><strong>{{ decimal(data.effectiveness_metrics?.average_score_improvement,2) }}</strong></div></section>
        <article class="panel"><div class="panel-title"><div><h3>处置效果评价</h3><span>关闭后以 30 天为观察窗口，对比案件基线与当前风险表现</span></div><el-button type="primary" :icon="CircleCheck" :loading="evaluating" @click="runEffectiveness">生成评价</el-button></div>
          <el-table :data="data.latest_effectiveness || []" size="small" border max-height="470"><el-table-column prop="customer_no" label="客户编号" min-width="145" /><el-table-column label="关闭时间" min-width="132"><template #default="{ row }">{{ formatDate(row.closed_at) }}</template></el-table-column><el-table-column label="评分变化" width="100" align="right"><template #default="{ row }">{{ number(row.baseline_risk_score) }} → {{ number(row.current_risk_score) }}</template></el-table-column><el-table-column label="当前 PD" width="90" align="right"><template #default="{ row }">{{ percent(row.current_pd) }}</template></el-table-column><el-table-column label="衰退 LGD" width="92" align="right"><template #default="{ row }">{{ percent(row.current_lgd_downturn) }}</template></el-table-column><el-table-column label="逾期/违约" width="96" align="right"><template #default="{ row }">{{ number(row.overdue_count) }}/{{ number(row.debt_default_count) }}</template></el-table-column><el-table-column label="评价" width="104"><template #default="{ row }"><el-tag size="small" :type="effectType(row.effectiveness_status)" effect="plain">{{ effectLabel(row.effectiveness_status) }}</el-tag></template></el-table-column><el-table-column prop="conclusion" label="结论" min-width="260" show-overflow-tooltip /></el-table>
        </article>
      </el-tab-pane>
    </el-tabs>

    <el-dialog v-model="limitVisible" title="调整组合风险限额" width="460px"><el-form :model="limitForm" label-width="90px"><el-form-item label="范围"><el-input v-model="limitForm.scope_name" disabled /></el-form-item><el-form-item label="指标"><el-input v-model="limitForm.metric_code" disabled /></el-form-item><el-form-item label="限额"><el-input-number v-model="limitForm.limit_amount" :min="1" :precision="2" :step="100000" controls-position="right" /></el-form-item><el-form-item label="预警比例"><el-input-number v-model="limitForm.warning_ratio" :min="0.01" :max="1" :precision="2" :step="0.05" controls-position="right" /></el-form-item><el-form-item label="责任人"><el-input v-model="limitForm.owner" /></el-form-item><el-form-item label="状态"><el-switch v-model="limitForm.enabled" active-text="启用" inactive-text="停用" /></el-form-item></el-form><template #footer><el-button @click="limitVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveLimit">保存</el-button></template></el-dialog>
    <el-dialog v-model="preferenceVisible" title="个性工作台设置" width="500px"><el-form label-width="100px"><el-form-item label="工作角色"><el-select v-model="preferenceForm.workspace_role" style="width:100%"><el-option label="风险经理" value="RISK_MANAGER" /><el-option label="管理层" value="EXECUTIVE" /><el-option label="模型人员" value="MODEL_ANALYST" /></el-select></el-form-item><el-form-item label="默认页面"><el-select v-model="preferenceForm.default_tab" style="width:100%"><el-option label="集中度与限额" value="limits" /><el-option label="限额前瞻" value="forecast" /><el-option label="压力测试" value="stress" /><el-option label="集团客户风险" value="groups" /><el-option label="模型生命周期" value="lifecycle" /><el-option label="模型回溯" value="backtest" /><el-option label="预警效果" value="effectiveness" /></el-select></el-form-item><el-form-item label="显示密度"><el-segmented v-model="preferenceForm.density_mode" :options="[{label:'舒适',value:'COMFORTABLE'},{label:'紧凑',value:'COMPACT'}]" /></el-form-item></el-form><template #footer><el-button @click="preferenceVisible=false">取消</el-button><el-button type="primary" :loading="preferenceSaving" @click="savePreference">保存设置</el-button></template></el-dialog>
    <el-drawer v-model="groupVisible" size="min(820px,100%)" :title="selectedGroup?.group_name || '集团成员明细'">
      <el-table v-loading="groupLoading" :data="groupMembers" size="small" border><el-table-column prop="customer_name" label="成员客户" min-width="180" show-overflow-tooltip /><el-table-column prop="relationship_type" label="关系" width="105" /><el-table-column label="持股比例" width="92" align="right"><template #default="{ row }">{{ percent(row.ownership_ratio) }}</template></el-table-column><el-table-column label="担保" width="70"><template #default="{ row }">{{ row.guarantee_flag ? '是' : '否' }}</template></el-table-column><el-table-column label="EAD" min-width="105" align="right"><template #default="{ row }">{{ compactAmount(row.ead_amount) }}</template></el-table-column><el-table-column prop="overdue_count" label="逾期" width="70" align="right" /><el-table-column prop="default_count" label="违约" width="70" align="right" /></el-table>
    </el-drawer>
