</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { CircleCheck, DataAnalysis, Refresh, Setting, TrendCharts } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import http from '../api/http'

const data = ref({})
const loading = ref(false), capturing = ref(false), backtesting = ref(false), evaluating = ref(false), saving = ref(false), stressing = ref(false)
const activeTab = ref('limits'), dimension = ref('industry'), limitVisible = ref(false)
const scenarioCode = ref('MILD_DOWNTURN'), groupVisible = ref(false), groupLoading = ref(false), selectedGroup = ref(null), groupMembers = ref([])
const preferenceVisible = ref(false), preferenceSaving = ref(false)
const preferenceForm = reactive({ workspace_role: 'RISK_MANAGER', default_tab: 'limits', density_mode: 'COMFORTABLE' })
const limitForm = reactive({ id: null, scope_name: '', metric_code: '', limit_amount: 0, warning_ratio: 0.8, owner: '', enabled: true })
const summary = computed(() => data.value.summary || {})
const concentrationRows = computed(() => data.value[`${dimension.value}_concentration`] || [])
onMounted(load)
async function load() { loading.value = true; try { data.value = await http.get('/api/risks/portfolio-management'); const preference=data.value.workbench_preference; if(preference){Object.assign(preferenceForm,{workspace_role:preference.workspace_role||'RISK_MANAGER',default_tab:preference.default_tab||'limits',density_mode:preference.density_mode||'COMFORTABLE'}); activeTab.value=preferenceForm.default_tab} } finally { loading.value = false } }
async function capture() { capturing.value = true; try { await http.post('/api/risks/portfolio-management/limit-snapshots'); await load() } finally { capturing.value = false } }
async function runBacktest() { backtesting.value = true; try { const result = await http.post('/api/risks/portfolio-management/backtests'); data.value.latest_backtest = result.results || []; activeTab.value = 'backtest' } finally { backtesting.value = false } }
async function runEffectiveness() { evaluating.value = true; try { const result = await http.post('/api/risks/portfolio-management/alert-effectiveness'); data.value.latest_effectiveness = result.results || []; activeTab.value = 'effectiveness' } finally { evaluating.value = false } }
async function runStress() { stressing.value = true; try { const result = await http.post('/api/risks/portfolio-management/stress-tests', { scenario_code: scenarioCode.value }); data.value.latest_stress_results = result.results || []; activeTab.value = 'stress' } finally { stressing.value = false } }
async function openGroup(row) { selectedGroup.value = row; groupVisible.value = true; groupLoading.value = true; try { const result = await http.get(`/api/risks/portfolio-management/groups/${encodeURIComponent(row.group_code)}/members`); groupMembers.value = result.members || [] } finally { groupLoading.value = false } }
async function savePreference() { preferenceSaving.value=true; try { await http.put('/api/risks/portfolio-management/workbench-preference',{...preferenceForm,visible_modules:['limits','forecast','stress','groups','lifecycle','backtest','effectiveness']}); activeTab.value=preferenceForm.default_tab; preferenceVisible.value=false; ElMessage.success('工作台设置已保存') } finally { preferenceSaving.value=false } }
function editLimit(row) { Object.assign(limitForm, { id: row.id, scope_name: row.scope_name, metric_code: metricLabel(row.metric_code), limit_amount: Number(row.limit_amount), warning_ratio: Number(row.warning_ratio), owner: row.owner || '', enabled: row.status === 'ENABLED' }); limitVisible.value = true }
async function saveLimit() { saving.value = true; try { const result = await http.put(`/api/risks/portfolio-management/limits/${limitForm.id}`, { limit_amount: limitForm.limit_amount, warning_ratio: limitForm.warning_ratio, owner: limitForm.owner, status: limitForm.enabled ? 'ENABLED' : 'DISABLED' }); data.value.limit_monitor = result.limit_monitor || []; data.value.summary = { ...(data.value.summary || {}), ...(result.summary || {}) }; limitVisible.value = false } finally { saving.value = false } }
function number(value) { return Number(value || 0).toLocaleString('zh-CN') }
function decimal(value, digits = 2) { return Number(value || 0).toFixed(digits) }
function amount(value) { return `¥${Number(value || 0).toLocaleString('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` }
function compactAmount(value) { const v = Number(value || 0); return v >= 100000000 ? `¥${(v / 100000000).toFixed(2)}亿` : v >= 10000 ? `¥${(v / 10000).toFixed(2)}万` : amount(v) }
function percent(value) { return `${(Number(value || 0) * 100).toFixed(2)}%` }
function signedPercent(value) { const v = Number(value || 0); return `${v >= 0 ? '+' : ''}${(v * 100).toFixed(2)}%` }
function formatDate(value) { return value ? String(value).replace('T', ' ').slice(0, 16) : '-' }
function label(value) { return value || '-' }
function concentrationWidth(value) { const max = Math.max(...concentrationRows.value.map((item) => Number(item.ead_amount || 0)), 1); return `${Math.max(5, Number(value || 0) / max * 100)}%` }
function dimensionLabel(value) { return ({ INDUSTRY: '行业', PRODUCT: '产品', ORGANIZATION: '机构' })[value] || value }
function metricLabel(value) { return ({ EAD: 'EAD', EL_DOWN: '衰退 EL' })[value] || value }
function limitType(value) { return ({ BREACH: 'danger', WARNING: 'warning', NORMAL: 'success', DISABLED: 'info' })[value] || 'info' }
function limitLabel(value) { return ({ BREACH: '超限', WARNING: '预警', NORMAL: '正常', DISABLED: '停用' })[value] || value }
function calibrationType(value) { return ({ RECALIBRATE: 'danger', WATCH: 'warning', STABLE: 'success' })[value] || 'info' }
function calibrationLabel(value) { return ({ RECALIBRATE: '需校准', WATCH: '关注', STABLE: '稳定' })[value] || value }
function effectType(value) { return ({ EFFECTIVE: 'success', PARTIAL: 'warning', INEFFECTIVE: 'danger', OBSERVING: 'info' })[value] || 'info' }
function effectLabel(value) { return ({ EFFECTIVE: '有效', PARTIAL: '部分有效', INEFFECTIVE: '无效', OBSERVING: '观察中' })[value] || value }
</script>

